rows = list(csv.DictReader(open('hlz-sort-year-raw.csv')))
assert len(rows)==434, len(rows)
assert len(M)==434, len(M)
out=[]
for r,(st,fam,note) in zip(rows,M):
    detail = f"HLZ sort_year row; year={r['year'] or 'n/a'}; type={r['type'] or 'n/a'}; journal={r['journal'] or 'n/a'}; ref={r['short_ref'] or 'continuation row of preceding paper'}; HLZ no.={'Common '+r['common_no'] if r['common_no'] else ('Indi. '+r['indi_no'] if r['indi_no'] else 'unnumbered (repeat/variant claim)')}; formation={ (r['formation'] or '')[:110] }"
    out.append({'catalog':'HLZ2016','entry_name':r['risk_factor'],'entry_detail':detail,'state':st,'program_family':fam,'notes':note})
with open('CATALOG-MAP-HLZ.csv','w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=['catalog','entry_name','entry_detail','state','program_family','notes'])
    w.writeheader(); w.writerows(out)
print(collections.Counter(o['state'] for o in out))
print('NEW families:', sorted(set(o['program_family'] for o in out if o['state']=='NEW')))
print('CLOSED rows:', sum(1 for o in out if o['state']=='CLOSED'))
print('EXISTING families:', len(set(o['program_family'] for o in out if o['state']=='EXISTING')))
